 $("#page-title").textContent="Supporting Evidence";
 $("#screen").innerHTML='<button class="secondary" id="back-supporting-course" type="button">‹ Back to course</button><div class="card"><div class="section-title">PORTFOLIO</div><h2>Supporting Evidence</h2><p>Anything else you want to keep as evidence for this course.</p></div><div class="supporting-list"><button type="button" class="card supporting-type" data-supporting-type="photo">${supportingCardIcon("photo")}<span class="supporting-type-copy"><strong>Take a photo</strong></span></button><button type="button" class="card supporting-type" data-supporting-type="video">${supportingCardIcon("video")}<span class="supporting-type-copy"><strong>Record a video</strong></span></button><button type="button" class="card supporting-type" data-supporting-type="audio">${supportingCardIcon("audio")}<span class="supporting-type-copy"><strong>Record Audio</strong></span></button><button type="button" class="card supporting-type" data-supporting-type="document">${supportingCardIcon("document")}<span class="supporting-type-copy"><strong>Upload a file</strong></span></button></div>';
